class Solution {
    public: vector<string> reorderLogFiles(vector<string>& logs){
        stable_sort(logs.begin(),logs.end(),[](const string& a,const string& b){
            int sa=a.find(' '),sb=b.find(' ');
            bool da=isdigit(a[sa+1]),db=isdigit(b[sb+1]);
            if(da&&db)return false;
            if(da!=db)return !da;
            string ca=a.substr(sa+1),cb=b.substr(sb+1);
            return ca==cb?a.substr(0,sa)<b.substr(0,sb):ca<cb;
        });
        return logs;
    }
};
